B.apr=new A.I(386,B.a3i)
B.XH=s(["Diagnostics: every dictated phrase logs where it landed, so a \u201cmy words vanished\u201d report is answerable from the log."],t.s)
B.ant=new A.I(385,B.XH)
B.a1Q=s(["Putting the cursor in an item while recording resumes dictation there (it used to stay paused)."],t.s)
B.amg=new A.I(384,B.a1Q)
