B.akW=new A.I(336,B.Xk)
B.Y6=s(["Dictate into a note IN PLACE \u2014 tap a note\u2019s mic and your words now stream into THAT box (no separate \u201cnew\u201d box); \u201cend note\u201d saves them to it."],t.s)
B.an5=new A.I(335,B.Y6)
